input.old_string:
label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 6px }
input { width: 100%; padding: 10px 12px; margin-bottom: 16px; border: 1px solid #cdc6be; border-radius: 6px; font-size: 15px }
.row { display: flex; gap: 14px }
.row > div { flex: 1 }
button { width: 100%; padding: 12px; background: #8c3b2e; color: #fff; border: 0; border-radius: 6px; font-size: 15px; font-weight: 600; cursor: pointer }

input.new_string:
